/**
 * Supply-chain tripwire: the committed pnpm lockfile must record exactly the
 * `pnpm.overrides` declared in package.json, and the pnpm version is pinned
 * in ONE place (package.json `packageManager`).
 *
 * Why: when the lock is regenerated by a different pnpm than the one CI
 * uses, the top-level `overrides:` block can be dropped or rewritten. A
 * lockfile without it installs the un-pinned (advisory-range) transitive
 * versions, and `pnpm install --frozen-lockfile` fails with
 * ERR_PNPM_LOCKFILE_CONFIG_MISMATCH. Pinning `packageManager` gives
 * dependabot, corepack and pnpm/action-setup the same pnpm, so the
 * workflows must not carry a second `version:` that could drift from it.
 */
import { describe, expect, it } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(__dirname, "..", "..");
const PINNED_PNPM = "pnpm@10.33.0";

function unquote(s: string): string {
  const t = s.trim();
  if (t.length >= 2 && (t[0] === "'" || t[0] === '"') && t[t.length - 1] === t[0]) {
    return t.slice(1, -1).replace(/''/g, "'");
  }
  return t;
}

/**
 * Parse the top-level `overrides:` mapping of a pnpm v9 lockfile. Returns
 * null when the block is absent. Only the flat `key: value` shape pnpm
 * writes for this block is accepted; anything else throws so the guard
 * fails closed instead of silently skipping entries.
 */
function parseLockOverrides(lock: string): Record<string, string> | null {
  const lines = lock.split(/\r?\n/);
  const start = lines.findIndex((l) => /^overrides:\s*$/.test(l));
  if (start === -1) return null;
  const out: Record<string, string> = {};
  for (let i = start + 1; i < lines.length; i++) {
    const line = lines[i]!;
    if (line.trim() === "") continue;
    if (!/^\s/.test(line)) break; // next top-level key
    const m = /^ {2}((?:'[^']*'|"[^"]*"|[^:\s][^:]*?)):\s+(.+)$/.exec(line);
    if (!m) throw new Error(`unparseable overrides line ${i + 1}: ${line}`);
    const key = unquote(m[1]!);
    if (key in out) throw new Error(`duplicate override key in lockfile: ${key}`);
    out[key] = unquote(m[2]!);
  }
  return out;
}

/** Differences between declared and locked overrides; empty when in sync. */
function overrideDrift(
  declared: Record<string, string>,
  locked: Record<string, string> | null,
): string[] {
  if (locked === null) {
    return Object.keys(declared).length ? ["lockfile has no overrides: block"] : [];
  }
  const out: string[] = [];
  for (const [k, v] of Object.entries(declared)) {
    if (!(k in locked)) out.push(`missing in lock: ${k}`);
    else if (locked[k] !== v) out.push(`value drift: ${k} (package.json ${v}, lock ${locked[k]})`);
  }
  for (const k of Object.keys(locked)) {
    if (!(k in declared)) out.push(`extra in lock: ${k}`);
  }
  return out;
}

const pkg = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")) as {
  packageManager?: string;
  pnpm?: { overrides?: Record<string, string> };
};
const lockText = readFileSync(join(ROOT, "pnpm-lock.yaml"), "utf8");

describe("pnpm lockfile overrides match package.json pnpm.overrides", () => {
  it("package.json declares overrides and the lockfile records the same set", () => {
    const declared = pkg.pnpm?.overrides ?? {};
    expect(Object.keys(declared).length).toBeGreaterThan(0);
    expect(overrideDrift(declared, parseLockOverrides(lockText))).toEqual([]);
  });

  describe("negative controls (synthetic lockfiles)", () => {
    const declared = { tmp: ">=0.2.6", "ws@8": ">=8.21.0", "minimatch@3>brace-expansion": ">=1.1.18 <2.0.0" };
    const good = [
      "lockfileVersion: '9.0'",
      "",
      "overrides:",
      "  tmp: '>=0.2.6'",
      "  ws@8: '>=8.21.0'",
      "  minimatch@3>brace-expansion: '>=1.1.18 <2.0.0'",
      "",
      "importers:",
      "  .: {}",
    ].join("\n");

    it("in-sync lock passes", () => {
      expect(overrideDrift(declared, parseLockOverrides(good))).toEqual([]);
    });

    it("a lock with the overrides block dropped is rejected", () => {
      const dropped = good.replace(/overrides:\n(?: {2}.*\n)+/, "");
      expect(parseLockOverrides(dropped)).toBeNull();
      expect(overrideDrift(declared, parseLockOverrides(dropped))).toEqual([
        "lockfile has no overrides: block",
      ]);
    });

    it("a missing entry, a changed value and an extra entry are each rejected", () => {
      const missing = good.replace("  ws@8: '>=8.21.0'\n", "");
      expect(overrideDrift(declared, parseLockOverrides(missing))).toEqual(["missing in lock: ws@8"]);
      const drifted = good.replace("'>=0.2.6'", "'>=0.2.4'");
      expect(overrideDrift(declared, parseLockOverrides(drifted))).toEqual([
        "value drift: tmp (package.json >=0.2.6, lock >=0.2.4)",
      ]);
      const extra = good.replace("  tmp:", "  lodash: '>=4.17.21'\n  tmp:");
      expect(overrideDrift(declared, parseLockOverrides(extra))).toEqual(["extra in lock: lodash"]);
    });

    it("an unparseable overrides line fails closed", () => {
      const nested = good.replace("  tmp: '>=0.2.6'", "  tmp:\n    nested: x");
      expect(() => parseLockOverrides(nested)).toThrow(/unparseable/);
    });
  });
});

describe("pnpm version has a single source of truth", () => {
  it(`package.json pins packageManager to ${PINNED_PNPM}`, () => {
    expect(pkg.packageManager).toBe(PINNED_PNPM);
  });

  it("no workflow passes a pnpm version to pnpm/action-setup", () => {
    const dir = join(ROOT, ".github", "workflows");
    const offenders: string[] = [];
    for (const f of readdirSync(dir).filter((n) => /\.ya?ml$/.test(n))) {
      offenders.push(...actionSetupVersionPins(readFileSync(join(dir, f), "utf8")).map((l) => `${f}:${l}`));
    }
    expect(offenders).toEqual([]);
  });

  it("negative control: a version pin under pnpm/action-setup is detected", () => {
    const wf = [
      "    steps:",
      "      - name: Set up pnpm",
      "        uses: pnpm/action-setup@b906affcce14559ad1aafd4ab0e942779e9f58b1 # v4",
      "        with:",
      "          version: 10",
      "      - name: Set up Node",
      "        uses: actions/setup-node@v4",
      "        with:",
      "          node-version: '20'",
    ].join("\n");
    expect(actionSetupVersionPins(wf)).toEqual([5]);
    expect(actionSetupVersionPins(wf.replace("          version: 10\n", ""))).toEqual([]);
  });
});

/** 1-based line numbers of `version:` keys inside a pnpm/action-setup step's `with:`. */
function actionSetupVersionPins(yaml: string): number[] {
  const lines = yaml.split(/\r?\n/);
  const hits: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    if (!/^\s*(?:-\s+)?uses:\s*pnpm\/action-setup@/.test(lines[i]!)) continue;
    const stepIndent = lines[i]!.indexOf("uses:");
    for (let j = i + 1; j < lines.length; j++) {
      const l = lines[j]!;
      if (l.trim() === "") continue;
      const indent = l.length - l.trimStart().length;
      if (indent < stepIndent) break; // next step or next job
      if (/^\s*version:\s*\S/.test(l)) hits.push(j + 1);
    }
  }
  return hits;
}
